const n=`# Cesium 沙盒代码使用说明

## 一、准备工作
1. 打开 Cesium 沙盒网站：https://sandcastle.cesium.com/
2. 确保您的浏览器支持 WebGL 且网络连接稳定

## 二、复制代码
1. 在下方找到完整的代码块
2. 点击代码块右上角的复制按钮（或使用快捷键 Ctrl+C/Command+C）
\`\`\`javascript
// 初始化 Cesium Viewer
const viewer = new Cesium.Viewer("cesiumContainer", {
    infoBox: false,
    selectionIndicator: false,
    shadows: true,
    shouldAnimate: true,
});

// 封装动画值生成器，避免代码重复
class Oscillator {
    constructor(min, max, step) {
        this.min = min;
        this.max = max;
        this.step = step;
        this.value = min;
        this.increasing = true;
    }

    update() {
        if (this.increasing) {
            this.value += this.step;
            if (this.value >= this.max) {
                this.value = this.max;
                this.increasing = false;
            }
        } else {
            this.value -= this.step;
            if (this.value <= this.min) {
                this.value = this.min;
                this.increasing = true;
            }
        }
        return this.value;
    }
}

// 创建 heading 和 pitch 动画控制器
const headingOscillator = new Oscillator(-90, 90, 0.05);
const pitchOscillator = new Oscillator(-45, 45, 0.05);

// 父实体位置
const position = Cesium.Cartesian3.fromDegrees(155, 25, 1750);

// 创建父实体
const parentEntity = viewer.entities.add({
    name: "父实体",
    position,
    orientation: new Cesium.CallbackProperty(() => {
        const heading = Cesium.Math.toRadians(headingOscillator.update());
        const pitch = Cesium.Math.toRadians(pitchOscillator.update());
        return Cesium.Quaternion.fromHeadingPitchRoll(
            new Cesium.HeadingPitchRoll(heading, pitch, 0)
        );
    }, false),
    model: {
        uri: "../SampleData/models/CesiumAir/Cesium_Air.glb",
        minimumPixelSize: 128,
        maximumScale: 20000,
    },
});

// 创建子实体
const childEntity = viewer.entities.add({
    name: "子实体",
    position: new Cesium.CallbackPositionProperty((time) => {
        const parentMatrix = parentEntity.computeModelMatrix(time);
        if (!parentMatrix) return undefined;
        
        const localOffset = new Cesium.Cartesian3(0, -5, -5);
        return Cesium.Matrix4.multiplyByPoint(
            parentMatrix,
            localOffset,
            new Cesium.Cartesian3()
        );
    }, false),
    orientation: new Cesium.CallbackProperty((time) => {
        const parentOrientation = parentEntity.orientation.getValue(time);
        if (!parentOrientation) return undefined;
        
        const localRotation = Cesium.Quaternion.fromHeadingPitchRoll(
            new Cesium.HeadingPitchRoll(
                Cesium.Math.toRadians(headingOscillator.update()),
                Cesium.Math.toRadians(pitchOscillator.update()),
                0
            )
        );
        
        return Cesium.Quaternion.multiply(
            parentOrientation,
            localRotation,
            new Cesium.Quaternion()
        );
    }, false),
    model: {
        uri: "../SampleData/models/CesiumAir/Cesium_Air.glb",
        scale: 0.25
    },
});
// 添加飞机和载荷之间的连接线
const lineEntity = viewer.entities.add({
    name: "连接线",
    polyline: {
        positions: new Cesium.CallbackProperty((time) => {
            const parentPosition = parentEntity.position.getValue(time);
            const childPosition = childEntity.position.getValue(time);
            
            if (parentPosition && childPosition) {
                return [parentPosition, childPosition];
            }
            
            return [];
        }, false),
        width: 4,
        material: Cesium.Color.YELLOW,
        clampToGround: false
    }
});
// 跟踪父实体
viewer.trackedEntity = parentEntity;    
\`\`\`

## 三、粘贴到沙盒
1. 在 Cesium 沙盒页面中，找到代码编辑区域（默认显示的是 main.js 文件内容）
2. 全选现有代码（Ctrl+A/Command+A）并删除
3. 粘贴您刚才复制的代码（Ctrl+V/Command+V）

## 四、运行查看效果
1. 点击沙盒页面左上角的"运行"按钮（三角形图标）
![示例图片](data:image/png;base64,)
2. 等待加载完成，您将在右侧预览窗口中看到 Cesium 场景效果
3. 如果需要调整代码，可以直接在编辑区域修改后再次点击"运行"

## 五、常见问题
1. **无法加载地图**：检查网络连接，或尝试刷新页面
2. **代码报错**：确认复制的代码完整且没有遗漏任何符号
3. **效果不符合预期**：可能是您的代码中引用了外部资源，请确保相关资源可访问

## 六、注意事项
1. 本代码在 Cesium 最新稳定版本（1.95）上测试通过
2. 如果您的代码使用了特定的地形或影像服务，可能需要替换为您自己的服务地址
3. 沙盒中的代码不会自动保存，请自行备份重要代码片段

如有其他问题，请联系技术支持团队(ysuhan@yeah.net)。`;export{n as default};
